local function enableBoolValues(parent)
    for _, child in pairs(parent:GetDescendants()) do
        if child:IsA("BoolValue") then
            child.Value = true
        end
    end
end

enableBoolValues(game)

game:GetService("StarterGui"):SetCore("SendNotification", {
    Title = "Unlock Success!";
    Text = "Almost all available skins are successfully unlocked.";
    Icon = "rbxassetid://110780237082692";
    Duration = 5;
})
